struct MaterialParams {
  p_atlasSize: vec2f,
  p_filtered: f32,
  p_alphaCutoff: f32,
};
@group(2) @binding(0) var<uniform> material: MaterialParams;
@group(2) @binding(1) var tex_atlas: texture_2d<f32>;
@group(2) @binding(2) var material_sampler: sampler;

fn map01_props_base(atlas: texture_2d<f32>, atlasSampler: sampler, coord: vec2f) -> vec4f {
  return textureSampleLevel(atlas, atlasSampler, coord, 0.0);
}
const MATERIAL_MODEL: u32 = 1u;
const MATERIAL_FOG: bool = false;
fn material_surface(in: SurfaceInput) -> SurfaceOutput {
  var out = surface_defaults();
  let v0: vec2f = (in.uv * material.p_atlasSize);
  let v1: vec2f = floor(v0);
  let v2: vec2f = (v1 + 0.5);
  let v3: vec2f = (v2 / material.p_atlasSize);
  let v4: vec2f = vec2f(material.p_filtered);
  let v5: vec2f = mix(v3, in.uv, v4);
  let v6: vec4f = map01_props_base(tex_atlas, material_sampler, v5);
  let v7: vec3f = v6.xyz;
  let v8: f32 = v6.w;
  out.base_color = v7;
  out.alpha = v8;
  return out;
}
